import { eventBusService, MiniAppNavigatorParams } from "@core/service";

export interface OpenAppPayloadOnboarding {
    appName:
    | keyof MiniAppNavigatorParams
    | 'HypervergeApp'
    | 'HomeApp'
    | 'AuthApp';
    screen: string;
    data?: object;
}

const goToScreen = ({ appName, screenName }: { appName: OpenAppPayloadOnboarding['appName'], screenName: string }) => {
    eventBusService.emit<OpenAppPayloadOnboarding>('open_app', {
        appName: appName || 'HomeApp',
        screen: screenName,
    });
};

export default goToScreen;