import { HttpService } from '@core/service';
import { GetListCurrentAccountsPayload } from '@src/application/loan_collateral/queries/get_list_current_accounts/get_list_current_accounts_query';
import { BASE_URL_LOAN_API } from '@src/config';
import type { GetListCurrentAccountsResponse } from '@src/domain/entities/loan_collateral/get_list_current_accounts';
import type { IGetListCurrentAccountsRepository } from '@src/domain/interfaces/loan_collateral/get_list_current_accounts';
import { commonService } from '@src/infrastructure/network/networkService';
import uuid from 'react-native-uuid';

export class GetListCurrentAccountsRepository extends HttpService implements IGetListCurrentAccountsRepository {
    constructor() {
        super({ baseURL: BASE_URL_LOAN_API });
    }
    async getListCurrentAccounts(query: GetListCurrentAccountsPayload): Promise<GetListCurrentAccountsResponse> {
        const request = query as unknown as GetListCurrentAccountsPayload;
        const url = '/getListCurrentAccounts';
        const params = {
            requestId: uuid.v4(),
            channel: String(request.channel),
            ipRequest: String(request.ipRequest),
            language: String(request.language),
            deviceInfo: {
                deviceId: String(request.deviceInfo.deviceId),
                deviceName: String(request.deviceInfo.deviceName),
                os: String(request.deviceInfo.os),
                osVersion: String(request.deviceInfo.osVersion),
            },
            data: {
                clientNo: String(request.data.clientNo),
                productCode: String(request.data.productCode),
            },
        };
        const response = await this.post(url, params, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-loan-collateral' }),
        });
        return response.data as GetListCurrentAccountsResponse;
    }
}
