import React, { useEffect } from 'react';
import { BaseButton, BottomSheet, createStyles, PortalManager } from '@core/ui';
import { Image, Text, View } from 'react-native';
// import { INextArrow } from '@src/assets/icons';
import { useTranslation } from '@core/service';
import getImg from '@src/utils/getImg';

interface CallSupportProps {
    options: {
        icon: string;
        text: string;
        onPress: () => void;
    }[];
}

const CallSupport: React.FC<CallSupportProps> = ({ options }) => {
    const { t } = useTranslation('supports');
    const styles = useStyles();
    return (
        <BottomSheet id="customerSupport" onClose={() => { PortalManager.dismissAll() }}>
            <Text style={styles.supportTitle}>{t('title')}</Text>
            {options.map((option) => (
                <BaseButton
                    key={option.text}
                    style={styles.supportHeader}
                    onPress={option.onPress}
                >
                    {option?.icon && <Image source={getImg(option.icon)} style={styles.icon} />}
                    <Image source={getImg(option.icon)} />
                    <Text style={styles.supportItem}>{t(option.text)}</Text>
                    <View>
                        <Image source={getImg('/assets/images/icons/INextArrow.svg')} />
                        {/* <INextArrow /> */}
                    </View>
                </BaseButton>
            ))}
        </BottomSheet>
    );
};

const useStyles = createStyles((theme) => ({
    supportTitle: {
        ...theme.Typography.Title300.SemiBold,
        fontWeight: theme.FontWeight.bold,
        marginBottom: theme.Size.Vertical.Medium,
    },
    supportHeader: {
        gap: theme.Size.Horizontal.Regular,
        borderWidth: 1,
        borderColor: theme.Colors.Border.Neutral400,
        borderRadius: theme.BorderRadius.lg,
        marginTop: theme.Size.Vertical.Medium,
        padding: theme.Size.Vertical.Regular,
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'center',
        verticalAlign: 'center',
    },
    supportItem: {
        flex: 1,
        ...theme.Typography.TextBody.SemiBold,
        fontWeight: theme.FontWeight.bold,
    },
    icon: {
        width: theme.Size.hs(40),
        height: theme.Size.vs(40),
        resizeMode: 'contain',
    }
}));

export default CallSupport;
