import { injectable } from 'inversify';
import { ISubmitLoanProposalRepository } from '@src/domain/interfaces/loan_collateral/submit_loan_proposal';
import { SubmitLoanProposalResponse } from '@src/domain/entities/loan_collateral/submit_loan_proposal';
import { HttpService } from '@core/service';
import { BASE_URL_LOAN_API } from '@src/config';
import { SubmitLoanProposalPayload } from '@src/application/loan_collateral/queries/submit_loan_proposal/submit_loan_proposal_query';
import uuid from 'react-native-uuid';
import { commonService } from '@src/infrastructure/network/networkService';

@injectable()
export class SubmitLoanProposalRepository extends HttpService implements ISubmitLoanProposalRepository {
    constructor() {
        super({ baseURL: BASE_URL_LOAN_API });
    }
    async submitLoanProposal(query: SubmitLoanProposalPayload): Promise<SubmitLoanProposalResponse> {
        const request = query as unknown as SubmitLoanProposalPayload;
        const url = '/submitLoanProposal';
        const dataReq = {
            ...request,
            requestId: uuid.v4(),
        };

        const { data } = await this.post(url, dataReq, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-loan-collateral' }),
        });
        return data as SubmitLoanProposalResponse;
    }
}
