import React, { useEffect, useRef, useState } from 'react';
import { SafeAreaView, ScrollView, View, ImageBackground, Image, Alert, TextInput, Keyboard } from 'react-native';
import {
    ActionButton,
    BottomSheetManager,
    BottomSheet,
    Spacer,
    Text,
    GradientButton,
    PinInput,
    SimpleHeader,
    type BottomSheetRef,
    LoadingBlockerView,
} from '@core/ui';
import useCSS from '@src/presentation/style';

import { CURRENCY } from '@src/utils/constants';
import slice from './slice';
import { useNavigation } from '@react-navigation/native';
import { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import SectionLoanInfo from './components/SectionLoanInfo';
import SectionInfoDetail from './components/SectionInfoDetail';
import SectionCustomerInfo from './components/SectionCustomerInfo';
import BottomSheetTnC from '@src/presentation/components/bottomSheetTnC';
import { useDispatch, useSelector } from '@src/lib/redux';
import {
    selectAccount,
    selectDepositRateMethodDesc,
    selectDisbursementDate,
    selectEmail,
    selectIntExpected,
    selectLoanAmount,
    selectMaturityDate,
    selectPaymentAcct,
    selectLoanIntRate,
    selectStatus,
    selectPhoneNumber,
    selectContractNo,
    selectMinAmount,
    selectMaxAmount,
    selectAvailableOutstanding,
    selectResultCodeInitLoanProposal,
    selectResultCodeGenerateContract,
    selectDepositRateMethod,
    selectLoanSubType,
    selectLoanPurposeName,
    selectLoanPurposeDesc,
    selectBranchId,
    selectProductCode,
    selectAgreementUUID,
    selectBillCode,
    selectResultCodeSubmitLoanProposal,
    selectError,
    selectPdfBase64,
} from './selector';
import { formatMoney, toText } from '@src/utils/currency';
import { fetchGenerateContract, fetchInitLoanProposal, fetchSubmitLoanProposal, fetchResendOTP, fetchGetListCurrentAccounts } from './thunk';
import type { GenerateContractPayload } from '@src/application/loan_collateral/queries/generate_contract/generate_contract_query';
import type { InitLoanProposalPayload } from '@src/application/loan_collateral/queries/init_loan_proposal/init_loan_proposal_query';
import type { SubmitLoanProposalPayload } from '@src/application/loan_collateral/queries/submit_loan_proposal/submit_loan_proposal_query';
import { selectClientNo } from '@src/presentation/loan_products/selector';
import { formatDate, IS_IOS, useTranslation } from '@core/service';
import { ResendOTPPayload } from '@src/application/loan_collateral/queries/resend_otp/resend_otp_query';
import { GetListCurrentAccountsPayload } from '@src/application/loan_collateral/queries/get_list_current_accounts/get_list_current_accounts_query';
import getImg from '@src/utils/getImg';
import ContentOTP from './components/ContentOTP';
import CustomHeader from '@src/presentation/components/header/CustomHeader';

const CollateralConfirmScreen = () => {
    const css = useCSS();
    const dispatch = useDispatch();
    const navigation = useNavigation<MainStackNavigationProp>();
    const { t } = useTranslation(['module_collateral']);

    const clientNo = useSelector(selectClientNo);

    const error = useSelector(selectError);
    const account = useSelector(selectAccount);
    const status = useSelector(selectStatus);
    const loanAmount = useSelector(selectLoanAmount);
    const minAmount = useSelector(selectMinAmount);
    const maxAmount = useSelector(selectMaxAmount);
    const loanIntRate = useSelector(selectLoanIntRate);
    const maturityDate = useSelector(selectMaturityDate);
    const depositRateMethod = useSelector(selectDepositRateMethod);
    const depositRateMethodDesc = useSelector(selectDepositRateMethodDesc);
    const paymentAcct = useSelector(selectPaymentAcct);
    const intExpected = useSelector(selectIntExpected);
    const email = useSelector(selectEmail);
    const disbursementDate = useSelector(selectDisbursementDate);
    const phoneNumber = useSelector(selectPhoneNumber);
    const contractNo = useSelector(selectContractNo);
    const availableOutstanding = useSelector(selectAvailableOutstanding);
    const loanPurposeDesc = useSelector(selectLoanPurposeDesc);
    const loanPurposeName = useSelector(selectLoanPurposeName);
    const loanSubType = useSelector(selectLoanSubType);
    const branchId = useSelector(selectBranchId);
    const productCode = useSelector(selectProductCode);

    const resultCodeInitLoanProposal = useSelector(selectResultCodeInitLoanProposal);

    const resultCodeGenerateContract = useSelector(selectResultCodeGenerateContract);
    const pdfBase64 = useSelector(selectPdfBase64);
    const agreementUUID = useSelector(selectAgreementUUID);
    const billCode = useSelector(selectBillCode);

    const resultCodeSubmitLoanProposal = useSelector(selectResultCodeSubmitLoanProposal);

    const refBSOTP = useRef<BottomSheetRef>(null);
    const refBSOTPLoading = useRef<BottomSheetRef>(null);
    const refBSTnC = useRef<BottomSheetRef>(null);
    const [messageOTP, setMessageOTP] = useState('');

    const [defaultValueOTP, setDefaultValueOTP] = useState('');

    const [currentEmail, setCurrentEmail] = useState('');
    const [currentBranch, setCurrentBranch] = useState('');
    const [currentPaymentAcct, setCurrentPaymentAcct] = useState('');

    const [pressedConfirmButton, setPressedConfirmButton] = useState(false);

    const payloadSubmit: SubmitLoanProposalPayload['data'] = {
        clientNo: clientNo,
        // userId: 'anhthyanh6489',
        // proposalID: 'ea1258a4-1f01-4ca8-a765-97ce76737104',
        loanAmt: loanAmount,
        intRate: loanIntRate?.toString(),
        disbursementDate: formatDate(disbursementDate),
        maturityDate: formatDate(maturityDate),
        priPayment: depositRateMethod,
        loanPurpose: loanPurposeName,
        loanPurposeSpec: loanPurposeDesc,
        loanSubType: loanSubType,
        branch: branchId,
        paymentAcct: paymentAcct,
        email: email,
        phoneNo: phoneNumber,
        intAmount: intExpected,
        contractNo: contractNo,
        // beneficiaryDepositAcct: '002704070010003',
        agreementUUID: agreementUUID,
        billCode: billCode,
        otp: '',
        productCode: productCode,
        listCollaterals: [
            {
                acctNo: account.accountNo,
                collatCode: account.collatCode, // loại tài sản đảm bảo
                collateralAmt: (Number(account.balance) - loanAmount).toString(), // giá trị tài sản đảm bảo
                usableAmt: account.balance, // giá trị có thể dùng để bảo đảm cho khoản vay
                asignAmt: loanAmount, // giá trị phân bổ
                intRate: account?.intRate,
            },
        ],
    };

    const handleValueChangeOTP = (otp: string) => {
        if (otp.length >= 6) {
            // const dataPayload: SubmitLoanProposalPayload['data'] = payloadSubmit;
            // dispatch(fetchSubmitLoanProposal(dataPayload));
            // Keyboard.dismiss();
        }
    };

    const handleResendOTP = () => {
        setDefaultValueOTP('');
        const dataPayload: ResendOTPPayload['data'] = {
            agreementUUID: agreementUUID,
        };
        dispatch(fetchResendOTP(dataPayload));
    };

    const handleConfirm = () => {
        setPressedConfirmButton(true);

        // dispatch(slice.actions.resetAPI());
        if (Number(loanAmount) < Number(minAmount) || Number(loanAmount) >= Number(maxAmount)) {
            // không đủ tiền vay
            Alert.alert('Thông báo', `Tối thiểu ${minAmount} VND và tối đa ${Number(maxAmount) - 1} VND`, [
                { text: 'OK', onPress: () => console.log('OK Pressed') },
            ]);
        } else if (loanAmount > Number(account.balance) || loanAmount + intExpected > Number(account.depositAcctAccruedAmt)) {
            // không đủ tiền
            Alert.alert('Thông báo', 'Vui lòng điều chỉnh giảm số tiền vay, lý do: vượt hạn mức của Sổ tiết kiệm.', [
                { text: 'OK', onPress: () => console.log('OK Pressed') },
            ]);
        } else if (!paymentAcct?.trim?.()) {
            // Alert.alert('Thông báo', 'Bạn chưa chọn tài khoản nhận giải ngân & trích nợ tự động', [{ text: 'OK', onPress: () => console.log('OK Pressed') }]);
            // } else if (Number(loanAmount) > Number(availableOutstanding)) {
            //     Alert.alert(
            //         'Thông báo',
            //         `Theo quy định tại Thông tư 39/2016/TT-NHNN (được sửa đổi, bổ sung bởi Thông tư 06/2023/TT-NHNN), Dư nợ tối đa của Khách hàng vay vốn tiêu dùng phục vụ nhu cầu đời sống (thực hiện bằng phương tiện điện tử) tối đa là 100 triệu đồng. Số tiền vay tối đa của Sản phẩm mà Quý khách đang lựa chọn là ${formatMoney(
            //             availableOutstanding,
            //         )} VND.`,
            //         [{ text: 'OK', onPress: () => console.log('OK Pressed') }],
            //     );
            //     // cập nhật số tiền vay vào store
            //     dispatch(slice.actions.setLoanAmount(Number(availableOutstanding)));
        } else {
            if (email !== currentEmail || branchId !== currentBranch || paymentAcct !== currentPaymentAcct) {
                dispatch(slice.actions.resetAPI());
                // lần đầu vào hoặc email && branch thay đổi thì generate hợp đồng
                const dataPayload: GenerateContractPayload['data'] = {
                    loanAmt: loanAmount,
                    intRate: loanIntRate?.toString(), // lãi suất vay vốn
                    maturityDate: formatDate(maturityDate), // ngày giải ngân
                    priPayment: depositRateMethod,
                    loanPurpose: loanPurposeName,
                    loanPurposeSpec: depositRateMethodDesc, // diễn giải mục đích vay
                    clientNo: clientNo,
                    paymentAcct: paymentAcct, // tài khoản nhận nợ
                    email: email,
                    phoneNo: phoneNumber,
                    intAmount: intExpected, // số tiền lãi vay
                    disbursementDate: formatDate(disbursementDate), // ngày đến hạn trả nợ
                    branch: branchId,
                    listCollaterals: [
                        {
                            acctNo: account?.accountNo,
                            intRate: account?.intRate?.toString(),
                        },
                    ],
                };
                dispatch(fetchGenerateContract(dataPayload));
                setCurrentEmail(email);
                setCurrentBranch(branchId);
                setCurrentPaymentAcct(paymentAcct);
            } else {
                showTnC();
            }
        }
    };

    const handleSubmit = () => {
        refBSTnC?.current?.close();
        dispatch(slice.actions.setInitLoanProposal());
        const dataPayload: InitLoanProposalPayload['data'] = {
            loanAmt: loanAmount,
            intRate: loanIntRate?.toString(),
            maturityDate: formatDate(maturityDate),
            clientNo: clientNo,
            paymentAcct: paymentAcct,
            intAmount: intExpected,
            listCollaterals: [
                {
                    acctNo: account?.accountNo,
                    intRate: account?.intRate,
                },
            ],
            contractNo: contractNo,
        };
        // call api khởi tạo khoản vay
        dispatch(fetchInitLoanProposal(dataPayload));
    };

    const handleClosePDFView = () => {
        showTnC();
    };

    const showTnC = () => {
        BottomSheetManager.show({
            render: (portalId) => (
                <BottomSheet ref={refBSTnC} id={portalId} title={t('screen_confirm.bs_tnc_title')}>
                    <BottomSheetTnC
                        onSubmit={handleSubmit}
                        data={[
                            {
                                id: '1',
                                content: (
                                    <Text style={[css.text_subheadline, css.font_regular]}>
                                        <Text style={[css.font_bold, css.text_red_600, css.underline]}>Điều khoản, điều kiện</Text> của HDBank
                                    </Text>
                                ),
                                title: 'Điều khoản, điều kiện của HDBank',
                                link: 'https://d1x17tzrw1vowc.cloudfront.net/Tn_C_TDL_224c216687.pdf',
                            },
                            {
                                id: '2',
                                content: (
                                    <Text style={[css.text_subheadline, css.font_regular]}>
                                        <Text style={[css.font_bold, css.text_red_600, css.underline]}>Hợp đồng vay cầm cố</Text> của HDBank
                                    </Text>
                                ),
                                title: 'Hợp đồng vay cầm cố của HDBank',
                                link: `data:application/pdf;base64,${pdfBase64}`,
                            },
                            {
                                id: '3',
                                content: (
                                    <Text style={[css.text_subheadline, css.font_regular]}>
                                        <Text style={[css.font_bold, css.text_red_600, css.underline]}>Điều khoản và điều kiện</Text> sử dụng Chứng thư số
                                        FPT-CA.
                                    </Text>
                                ),
                                title: 'Điều khoản và điều kiện sử dụng Chứng thư số FPT-CA',
                                link: 'https://d1x17tzrw1vowc.cloudfront.net/6_DKDK_CA_FPT_cce111940d.pdf',
                            },
                        ]}
                        onClosePDFView={handleClosePDFView}
                    />
                </BottomSheet>
            ),
        });
    };
    useEffect(() => {
        if (productCode !== '') {
            const payload: GetListCurrentAccountsPayload['data'] = {
                clientNo: clientNo,
                productCode: productCode,
            };
            dispatch(fetchGetListCurrentAccounts(payload));
        }
    }, [productCode]);

    useEffect(() => {
        if (resultCodeGenerateContract === '00' && pressedConfirmButton) {
            showTnC();
        }
    }, [resultCodeGenerateContract]);

    useEffect(() => {
        if (resultCodeInitLoanProposal === '00') {
            BottomSheetManager.show({
                render: (portalId) => (
                    <BottomSheet
                        ref={refBSOTP}
                        id={portalId}
                        title={t('screen_confirm.bs_otp_title')}
                        description={`${t('screen_confirm.bs_otp_desc')}*${phoneNumber.slice(-3)}`}
                        enableContentPanningGesture={false}
                        snapPoints={['80%']}
                        safeAreaBottomOffset={IS_IOS ? 370 : 0}>
                        <ContentOTP
                            payload={payloadSubmit}
                            onSubmit={() => {
                                if (refBSOTP) {
                                    refBSOTP.current?.close();
                                }
                            }}
                        />
                    </BottomSheet>
                ),
            });
        }
    }, [resultCodeInitLoanProposal]);

    useEffect(() => {
        if (resultCodeSubmitLoanProposal === '00') {
            // navigation.navigate('collateral_result');
            // refBSOTP?.current?.close();
        }
    }, [resultCodeSubmitLoanProposal]);

    useEffect(() => {
        if (error?.trim?.()) {
            Alert.alert('Thông báo', error);
            slice.actions.setError('');
        }
    }, [error]);

    return (
        <>
            <ImageBackground source={getImg('/assets/images/bg_body.jpg')} resizeMode='cover' style={[css.flex_1]}>
                <SafeAreaView style={[css.flex_1]}>
                    {/* <SimpleHeader allowGoBack title={t('screen_confirm.header_title')} onBackPress={() => navigation.goBack()} /> */}
                    <CustomHeader title={t('screen_confirm.header_title')} />
                    {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
                    <ScrollView style={[css.flex_1]}>
                        <View style={[css.mt_xLarge, css.mh_medium]}>
                            <View style={[css.rounded_medium, css.border_1, css.border_neutral_300, css.overflow_hidden]}>
                                <ImageBackground
                                    source={getImg('/assets/images/bg/bg_header_Loan_registration_card.png')}
                                    resizeMode='cover'
                                    style={[css.pt_medium, css.pb_regular, css.ph_medium]}>
                                    <Text style={[css.text_caption_200, css.font_regular]}>{t('screen_confirm.loan_amount')}</Text>
                                    <Text style={[css.text_title_200, css.font_bold]}>
                                        {formatMoney(loanAmount)} {CURRENCY}
                                    </Text>
                                    <Text style={[css.text_caption_200, css.font_regular, css.mt_small]}>{toText.convert(loanAmount)}</Text>
                                </ImageBackground>
                                <View style={[css.bg_white, css.pv_regular, css.ph_medium, css.bg_white]}>
                                    <SectionLoanInfo />
                                </View>
                            </View>
                            <Text style={[css.text_body, css.font_semibold, css.mt_medium, css.mb_base]}>{t('screen_confirm.details')}</Text>
                            <View
                                style={[
                                    css.rounded_medium,
                                    css.border_1,
                                    css.border_neutral_300,
                                    css.overflow_hidden,
                                    css.pv_regular,
                                    css.ph_medium,
                                    css.bg_white,
                                ]}>
                                <SectionInfoDetail />
                            </View>
                            <View style={[css.mt_medium, css.bg_orange_200, css.ph_medium, css.pv_regular, css.rounded_medium]}>
                                <View style={[css.row]}>
                                    <Image
                                        source={getImg('/assets/images/icons/icon_info_orange_600.png')}
                                        style={[css.shrink_0, css.mr_base, css.w_xLarge, css.ratio_square]}
                                    />
                                    <View style={[css.flex_1]}>
                                        <Text style={[css.text_subheadline, css.font_regular]}>{t('screen_confirm.note')}</Text>
                                    </View>
                                </View>
                            </View>
                            <Text style={[css.text_body, css.font_semibold, css.mt_medium, css.mb_base]}>{t('screen_confirm.details')}</Text>
                            <View
                                style={[
                                    css.rounded_medium,
                                    css.border_1,
                                    css.border_neutral_300,
                                    css.overflow_hidden,
                                    css.pv_regular,
                                    css.ph_medium,
                                    css.bg_white,
                                ]}>
                                <SectionCustomerInfo />
                            </View>
                        </View>
                        <View style={[css.p_medium]}>
                            <GradientButton gradientProps={{ type: 'primary' }} title={t('screen_confirm.btn_confirm')} onPress={handleConfirm} />
                        </View>
                    </ScrollView>
                </SafeAreaView>
            </ImageBackground>
        </>
    );
};

export default CollateralConfirmScreen;
