import React from 'react';
import { StyleProp, TextStyle, TouchableOpacity, View, ViewStyle } from 'react-native';
import { createStyles, Text, useTheme } from '@core/ui';
import { Trans } from 'react-i18next';

interface HighlightTitleProps {
    title: string;
    subtitle?: string;
    titleStyle?: StyleProp<TextStyle>;
    subtitleStyle?: StyleProp<TextStyle>;
    containerStyle?: StyleProp<ViewStyle>;
}

const HighlightTitle: React.FC<HighlightTitleProps> = ({ title, subtitle, titleStyle, subtitleStyle, containerStyle }) => {
    const styles = useStyles();
    const { theme } = useTheme();
    return (
        <View style={[styles.container, containerStyle]}>
            {/* <TouchableOpacity onPress={() => { console.log('touch title'); }}> */}
            <Text style={[styles.title, titleStyle]}>
                <Trans
                    defaults={title}
                    components={{
                        b: <Text style={{ color: theme.Colors.Main.Red }} />,
                    }}
                    onPressed={() => { console.log('click title'); }}
                />
            </Text>
            {/* </TouchableOpacity> */}
            {subtitle && (
                <Text style={[styles.subtitle, subtitleStyle]}>
                    <Trans
                        defaults={subtitle}
                        components={{
                            b: <Text style={{ color: theme.Colors.Main.Red, fontFamily: theme.Fonts.Bold }} />,
                        }}
                    />
                </Text>
            )}
        </View>
    );
};

export default HighlightTitle;

const useStyles = createStyles((theme) => ({
    container: {
        gap: theme.Size.Vertical.Base,
    },
    title: {
        ...theme.Typography.Title200.Semibold,
        // fontWeight: theme.FontWeight.medium,
    },
    subtitle: {
        ...theme.Typography.TextSubheadline.Regular,
    },
}));
