import React from 'react';
import { SafeAreaView, ScrollView, View, ImageBackground, Image } from 'react-native';
import { Text, useTheme, GradientButton, SimpleHeader } from '@core/ui';
import useCSS from '@src/presentation/style';
import { CURRENCY } from '@src/utils/constants';
import { useNavigation } from '@react-navigation/native';
import { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import { useDispatch, useSelector } from '@src/lib/redux';
import { selectAccount, selectLoanAmount } from '../collateral_confirm/selector';
import { formatMoney } from '@src/utils/currency';
import { formatDate, useTranslation } from '@core/service';
import moment from 'moment';
import { ProductSlice } from '@src/presentation/loan_products/slice';
import sliceConfirm from '@src/presentation/loan_collateral/collateral_confirm/slice';
import sliceAccounts from '@src/presentation/loan_collateral/collateral_accounts/slice';
import getImg from '@src/utils/getImg';
import AnimatedLottieView from 'lottie-react-native';
import { FireWorks } from '@src/assets/lottie';
import CustomHeader from '@src/presentation/components/header/CustomHeader';

const CollateralResultScreen = () => {
    const { theme } = useTheme();
    const css = useCSS();
    const dispatch = useDispatch();
    const { t } = useTranslation(['module_collateral']);

    const navigation = useNavigation<MainStackNavigationProp>();
    const account = useSelector(selectAccount);
    const loanAmount = useSelector(selectLoanAmount);

    const handleGoHome = () => {
        dispatch(ProductSlice.actions.resetClientInfo());
        dispatch(sliceAccounts.actions.resetAccounts());
        dispatch(sliceConfirm.actions.resetAPI());
        navigation.navigate('products');
    };

    return (
        <ImageBackground source={getImg('/assets/images/bg_body.jpg')} resizeMode='cover' style={[css.flex_1]}>
            <SafeAreaView style={[css.flex_1]}>
                {/* <SimpleHeader /> */}
                <CustomHeader />
                <ScrollView style={[]} contentContainerStyle={[css.flex_1]}>
                    <View style={[css.mt_medium, css.mh_medium]}>
                        <AnimatedLottieView loop autoPlay style={[{ width: theme.Scaling.ms(100) }, css.ratio_square]} source={FireWorks} />
                        <Text style={[css.text_title_200, css.font_semibold, css.mt_base]}>{t('screen_result.title')}</Text>
                        <Text style={[css.text_caption_100, css.text_neutral_600, css.font_regular, css.mt_base]}>{moment().format('HH:mm DD/MM/YYYY')}</Text>
                        <Text style={[css.text_subheadline, css.mt_base, css.font_regular]}>
                            {t('screen_result.row1_str1')}{' '}
                            <Text style={[css.text_red_600, css.font_bold]}>
                                {formatMoney(loanAmount)} {CURRENCY}
                            </Text>{' '}
                            {t('screen_result.row1_str2')} <Text style={[css.font_bold]}>{account?.accountNo}</Text>, {t('screen_result.row1_str3')}{' '}
                            <Text style={[css.font_bold]}>
                                {account?.intRate ? account?.intRate : '__'}%/{t('screen_result.year')}
                            </Text>{' '}
                            -{t('screen_result.row1_str4')} {account?.maturityDate ? formatDate(account?.maturityDate) : '__/__/____'}.
                        </Text>
                        <Text style={[css.mt_medium, css.text_subheadline, css.font_regular]}>
                            {t('screen_result.row2_str1')} <Text style={[css.font_bold]}>{t('screen_result.row2_str2')}</Text> {t('screen_result.row2_str3')}{' '}
                            <Text style={[css.font_bold]}>{t('screen_result.row2_str4')}</Text> {t('screen_result.row2_str5')}
                        </Text>
                    </View>
                    <View style={[css.p_medium, css.mt_auto]}>
                        <GradientButton gradientProps={{ type: 'primary' }} title={t('screen_result.btn_go_home')} onPress={handleGoHome} />
                    </View>
                </ScrollView>
            </SafeAreaView>
        </ImageBackground>
    );
};

export default CollateralResultScreen;
