import React from 'react';
import { View } from 'react-native';
import { createStyles, useTheme } from '@core/ui';
import { ColorValue } from 'react-native/Libraries/StyleSheet/StyleSheet';

export interface HeaderProgressProps {
    current: number;
    total: number;
    colors?: { previous?: ColorValue; active?: ColorValue; next?: ColorValue };
}

export const HeaderProgress: React.FC<HeaderProgressProps> = ({
    current,
    total,
    colors,
}) => {
    const styles = useStyles();
    const theme = useTheme();

    const calcColors = {
        previous: theme.theme.Colors.Main.Red,
        active: theme.theme.Colors.Main.Red,
        next: theme.theme.Colors.Background.Neutral500,
        ...colors,
    };

    return (
        <View style={styles.breadcrumbContainer}>
            {Array.from({ length: total }, (_, i) => {
                const stepIndex = i + 1;
                let backgroundColor;

                if (stepIndex < current) {
                    backgroundColor = calcColors.previous;
                } else if (stepIndex === current) {
                    backgroundColor = calcColors.active;
                } else {
                    backgroundColor = calcColors.next;
                }

                return (
                    <View key={stepIndex} style={[styles.step, { backgroundColor }]} />
                );
            })}
        </View>
    );
};

const useStyles = createStyles((theme) => ({
    breadcrumbContainer: {
        flexDirection: 'row',
    },
    step: {
        width: theme.Size.Horizontal.Medium,
        height: theme.Size.Vertical.Small,
        borderRadius: theme.BorderRadius.xs,
        backgroundColor: theme.Colors.Background.Neutral500,
        marginHorizontal: theme.Size.Horizontal.XSmall,
    },
}));
